export type Trait = { category: string; value: string };
export type Study = { id: string; title: string; subtitle: string; image: string; traits: Trait[]; inspiration: string; drift: string; question?: string };
export type Batch = {id:string;title:string;date:string;focus:string;direction:string;description:string;premise:string;studies:Study[];sceneTitle?:string;sceneSummary?:string;sceneLock?:string;sceneName?:string;referenceImage?:string;referenceLabel?:string};
const traits = (values: string[]): Trait[] => ['Lighting', 'Goofiness', 'Palette', 'Materials', 'Texture', 'Filter', 'Edges', 'Mood'].map((category, i) => ({ category, value: values[i] }));
const worldTraits=(values:string[],technology:string,culture:string,mystery:string):Trait[]=>[...traits(values),{category:'Technology',value:technology},{category:'Culture',value:culture},{category:'Mystery',value:mystery}];
